import React, { useEffect, useRef, useState } from "react";
import { api } from "@/lib/api";
import { Camera, Pill, Search, AlertTriangle, Check, RotateCcw, Info, Clock, AlertCircle, Star, RefreshCw } from "lucide-react";
import { toast } from "sonner";

export default function MedicineScanner() {
  const [mode, setMode] = useState("scan");
  const [scanning, setScanning] = useState(false);
  const [query, setQuery] = useState("");
  const [result, setResult] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [cameraStream, setCameraStream] = useState(null);
  const videoRef = useRef(null);
  const canvasRef = useRef(null);

  const startCamera = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({
        video: { facingMode: "environment", width: 1280, height: 720 }
      });
      setCameraStream(stream);
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
        videoRef.current.play();
      }
      setScanning(true);
    } catch (err) {
      toast.error("Camera access denied. Try manual search instead.");
      setMode("manual");
    }
  };

  const stopCamera = () => {
    if (cameraStream) {
      cameraStream.getTracks().forEach(track => track.stop());
      setCameraStream(null);
    }
    setScanning(false);
  };

  const captureImage = async () => {
    if (!videoRef.current) return;
    const canvas = canvasRef.current;
    const video = videoRef.current;
    canvas.width = video.videoWidth;
    canvas.height = video.videoHeight;
    canvas.getContext("2d").drawImage(video, 0, 0);
    stopCamera();
    toast.info("Camera captured. Please type the medicine name below.");
    setMode("manual");
  };

  const searchMedicine = async (name) => {
    const searchTerm = name || query;
    if (!searchTerm.trim()) return toast.error("Please enter a medicine name");
    setLoading(true);
    setError(null);
    try {
      const res = await api.post("/medicines/info", { name: searchTerm.trim() });
      setResult(res.data);
      setMode("result");
    } catch (err) {
      setError(err?.response?.data?.detail || "Medicine not found in database");
      setResult(null);
    }
    setLoading(false);
  };

  const addReminder = async () => {
    if (!result) return;
    try {
      await api.post("/medicines", {
        name: result.name,
        dose: result.dosage,
        morning: true,
        afternoon: false,
        night: false,
        notes: result.uses.slice(0, 100)
      });
      toast.success("Reminder added for " + result.name);
    } catch {
      toast.error("Could not add reminder");
    }
  };

  const reset = () => {
    setMode("scan");
    setResult(null);
    setError(null);
    setQuery("");
    stopCamera();
  };

  useEffect(() => {
    return () => stopCamera();
  }, []);

  return (
    <div className="max-w-5xl mx-auto" data-testid="medicine-scanner-page">
      <div className="glass-strong rounded-3xl p-6 flex items-center gap-3 mb-6">
        <div className="w-11 h-11 rounded-2xl bg-teal-100 grid place-items-center">
          <Camera className="w-5 h-5 text-teal-700" strokeWidth={2.5} />
        </div>
        <div>
          <h1 className="font-display text-3xl">AI Medicine Scanner</h1>
          <p className="text-sm text-slate-500">Scan a medicine strip or search by name.</p>
        </div>
      </div>

      {mode === "scan" && (
        <div className="glass rounded-3xl p-6">
          {!scanning ? (
            <div className="text-center py-10">
              <div className="w-24 h-24 mx-auto rounded-full bg-teal-100 grid place-items-center mb-4">
                <Camera className="w-10 h-10 text-teal-600" strokeWidth={2} />
              </div>
              <h2 className="font-display text-2xl mb-2">Scan Medicine Strip</h2>
              <p className="text-slate-500 mb-6">Point your camera at the medicine name on the strip/box.</p>
              <button
                data-testid="scanner-start"
                onClick={startCamera}
                className="px-8 py-3 rounded-full bg-teal-400 text-white font-bold hover:scale-105 transition inline-flex items-center gap-2"
              >
                <Camera className="w-5 h-5" /> Start Camera
              </button>
              <div className="mt-4">
                <button
                  onClick={() => setMode("manual")}
                  className="text-sm text-slate-500 hover:text-slate-800 underline"
                >
                  Or search manually
                </button>
              </div>
            </div>
          ) : (
            <div className="text-center">
              <div className="relative rounded-3xl overflow-hidden border-4 border-teal-200 mb-4 max-w-md mx-auto">
                <video ref={videoRef} autoPlay playsInline className="w-full" />
                <canvas ref={canvasRef} className="hidden" />
                <div className="absolute inset-0 border-4 border-teal-400 rounded-3xl opacity-60 pointer-events-none" />
                <div className="absolute top-4 left-4 bg-white/90 px-3 py-1 rounded-full text-xs font-bold text-teal-700">
                  Align medicine name in frame
                </div>
              </div>
              <div className="flex gap-3 justify-center">
                <button
                  data-testid="scanner-capture"
                  onClick={captureImage}
                  className="px-6 py-3 rounded-full bg-teal-400 text-white font-bold hover:scale-105 transition"
                >
                  <Camera className="w-5 h-5 inline mr-2" /> Capture
                </button>
                <button
                  onClick={stopCamera}
                  className="px-6 py-3 rounded-full bg-slate-200 text-slate-700 font-bold hover:bg-slate-300 transition"
                >
                  Cancel
                </button>
              </div>
            </div>
          )}
        </div>
      )}

      {mode === "manual" && (
        <div className="glass rounded-3xl p-6">
          <div className="flex items-center gap-3 mb-4">
            <div className="w-10 h-10 rounded-xl bg-blue-100 grid place-items-center">
              <Search className="w-5 h-5 text-blue-700" />
            </div>
            <h2 className="font-display text-xl">Search Medicine</h2>
          </div>
          <div className="flex gap-3">
            <input
              data-testid="scanner-search"
              value={query}
              onChange={(e) => setQuery(e.target.value)}
              onKeyDown={(e) => e.key === "Enter" && searchMedicine()}
              placeholder="Enter medicine name (e.g. Paracetamol, Ibuprofen)"
              className="flex-1 px-5 py-3 rounded-2xl bg-white/90 border border-white outline-none focus:ring-4 focus:ring-teal-200 text-sm"
            />
            <button
              data-testid="scanner-search-btn"
              onClick={() => searchMedicine()}
              disabled={loading}
              className="px-6 py-3 rounded-full bg-teal-400 text-white font-bold hover:scale-105 transition disabled:opacity-50"
            >
              {loading ? <RefreshCw className="w-5 h-5 animate-spin" /> : <Search className="w-5 h-5" />}
            </button>
          </div>
          <div className="mt-4">
            <button onClick={() => setMode("scan")} className="text-sm text-slate-500 hover:text-slate-800 underline">
              ← Back to camera scan
            </button>
          </div>
          {error && (
            <div className="mt-4 p-4 rounded-2xl bg-amber-50 border border-amber-200 text-amber-800 text-sm flex gap-2">
              <AlertTriangle className="w-5 h-5 shrink-0" />
              {error}
            </div>
          )}
        </div>
      )}

      {mode === "result" && result && (
        <div className="space-y-4">
          <div className="glass-strong rounded-3xl p-6 bg-gradient-to-br from-teal-50 to-white">
            <div className="flex items-start justify-between">
              <div className="flex items-center gap-2">
                <div className="w-10 h-10 rounded-xl bg-teal-100 grid place-items-center">
                  <Pill className="w-5 h-5 text-teal-700" />
                </div>
                <h2 className="font-display text-2xl">{result.name}</h2>
              </div>
              <button
                data-testid="scanner-add-reminder"
                onClick={addReminder}
                className="px-4 py-2 rounded-full bg-rose-400 text-white text-sm font-bold hover:scale-105 transition inline-flex items-center gap-1"
              >
                <Clock className="w-4 h-4" /> Add Reminder
              </button>
            </div>
          </div>

          <div className="grid md:grid-cols-2 gap-4">
            <div className="glass rounded-3xl p-5">
              <h3 className="font-display text-lg text-slate-700 flex items-center gap-2">
                <Info className="w-4 h-4 text-blue-500" /> Uses
              </h3>
              <p className="text-sm text-slate-600 mt-2">{result.uses}</p>
            </div>
            <div className="glass rounded-3xl p-5">
              <h3 className="font-display text-lg text-slate-700 flex items-center gap-2">
                <Check className="w-4 h-4 text-green-500" /> Dosage
              </h3>
              <p className="text-sm text-slate-600 mt-2">{result.dosage}</p>
            </div>
            <div className="glass rounded-3xl p-5">
              <h3 className="font-display text-lg text-slate-700 flex items-center gap-2">
                <AlertCircle className="w-4 h-4 text-amber-500" /> Side Effects
              </h3>
              <p className="text-sm text-slate-600 mt-2">{result.side_effects}</p>
            </div>
            <div className="glass rounded-3xl p-5">
              <h3 className="font-display text-lg text-slate-700 flex items-center gap-2">
                <Star className="w-4 h-4 text-purple-500" /> Expiry &amp; Storage
              </h3>
              <p className="text-sm text-slate-600 mt-2"><b>Expiry:</b> {result.expiry_info}</p>
              <p className="text-sm text-slate-600 mt-1"><b>Storage:</b> {result.storage}</p>
            </div>
          </div>

          <div className="glass rounded-3xl p-5">
            <h3 className="font-display text-lg text-slate-700 mb-3">Alternatives</h3>
            <div className="flex flex-wrap gap-2">
              {result.alternatives?.map((alt) => (
                <span key={alt} className="px-3 py-1.5 rounded-full bg-slate-100 text-sm text-slate-700">{alt}</span>
              ))}
            </div>
          </div>

          <div className="glass rounded-3xl p-5">
            <h3 className="font-display text-lg text-slate-700 flex items-center gap-2 mb-3">
              <AlertTriangle className="w-4 h-4 text-red-500" /> Drug Interactions
            </h3>
            <ul className="space-y-2">
              {result.drug_interactions?.map((interaction, i) => (
                <li key={i} className="text-sm text-slate-600 flex items-start gap-2">
                  <span className="w-1.5 h-1.5 rounded-full bg-red-400 mt-2 shrink-0" />
                  {interaction}
                </li>
              ))}
            </ul>
          </div>

          <div className="glass rounded-3xl p-4 text-xs text-slate-500">
            This information is for educational purposes only. Always consult your doctor or pharmacist before taking any medication.
          </div>

          <button
            onClick={reset}
            className="w-full py-3 rounded-full bg-slate-200 text-slate-700 font-bold hover:bg-slate-300 transition inline-flex items-center justify-center gap-2"
          >
            <RotateCcw className="w-4 h-4" /> Scan Another Medicine
          </button>
        </div>
      )}
    </div>
  );
}
